/bin/zsh -lc "python3 - <<'PY'
import json, hashlib
from pathlib import Path
from collections import Counter, defaultdict
from datetime import datetime
for name in ['regras.md','eventos.json']:
    print(name, hashlib.sha256(Path(name).read_bytes()).hexdigest())
events=json.loads(Path('eventos.json').read_text())
counts=Counter(e['event_id'] for e in events)
unique={}
for e in events:
    if e['event_id'] in unique:
        assert unique[e['event_id']]==e, 'Conflicting duplicate event'
    unique[e['event_id']]=e
start=datetime.fromisoformat('2026-10-10T00:00:00+00:00')
end=datetime.fromisoformat('2026-10-11T00:00:00+00:00')
time=lambda e: datetime.fromisoformat(e['em'].replace('Z','+00:00'))
payments=[e for e in unique.values() if e['tipo']=='pago' and e['moeda']=='BRL' and start<=time(e)<end]
refunds=defaultdict(int)
for e in unique.values():
    if e['tipo']=='estorno_confirmado' and time(e)<end:
        refunds[e['pedido']]+=e['valor']
channels={'loja':0,'web':0}
for p in payments:
    net=p['valor']-refunds[p['pedido']]
    channels[p['canal']]+=net
    print('included',p['pedido'],'payment',p['event_id'],'gross',p['valor'],'refund',refunds[p['pedido']],'net',net,'channel',p['canal'])
print('raw_count',len(events),'unique_count',len(unique),'duplicates',{k:v for k,v in counts.items() if v>1})
print(json.dumps({'pedidos_incluidos':sorted(p['pedido'] for p in payments),'receita_liquida_centavos':sum(channels.values()),'por_canal_centavos':channels},ensure_ascii=False))
PY"

